mapper.select:
select comment_id, comment_content, board_id, member_id, reg_date, parent_comment_id, del_yn
from comment
where comment_id = #{commentId}

mapper.update:
update comment 
set comment_content = #{commentContent} 
where comment_id = #{commentId}

update comment 
set comment_content = '삭제된 댓글입니다.', del_yn = 'Y' 
where comment_id = #{commentId}

mapper.select:
select cm.comment_id, cm.member_id, cm.board_id, cm.comment_content, cm.reg_date, b.board_title, (select count(*) from comment r where r.parent_comment_id = cm.comment_id and r.del_yn = 'N') as reply_cnt from comment cm join board b on cm.board_id = b.board_id where cm.member_id = #{memberId} and cm.del_yn = 'N'
and b.category_idx = #{category}
order by cm.reg_date desc limit #{start}, #{limit}
